INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch06$PT134-S1-Q3$batch06$, 134, 1, 3, $batch06$Method of Reasoning$batch06$, $batch06$Political scientist: Efforts to create a more egalitarian society are often wrongly criticized on the grounds that total equality would necessarily force everyone into a common mold. Equality is presumed by such critics to require unacceptably bland uniformity. But this is not so. By promoting complementary human interests, a society can achieve a greater and more prosperous equality while enhancing rather than minimizing diversity.$batch06$, $batch06$The political scientist's argument proceeds by$batch06$, $batch06$B$batch06$, true, $batch06$Batch 06; question text from local bank.$batch06$ FROM lr_sections s WHERE s.preptest=134 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$A$batch06$, $batch06$undermining a view by showing that its general acceptance would lead to undesirable consequences$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$A$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$B$batch06$, $batch06$rebutting an objection by attacking the assumption on which it is said to be based$batch06$, $batch06$Correct$batch06$, true FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$B$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$C$batch06$, $batch06$attacking a view by claiming that those who propose it are motivated only by self-interest$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$C$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$D$batch06$, $batch06$claiming that whatever is true of a group must be true of each of the members of the group$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$D$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch06$E$batch06$, $batch06$undermining an apparent counterexample to a universal claim$batch06$, $batch06$Bad Description$batch06$, false FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch06$E$batch06$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$The criticism that equality forces everyone into a common mold is wrong.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$By promoting complementary interests, a society can become more equal while increasing diversity.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The critics' objection rests on a hidden premise: equality requires uniformity. The political scientist goes straight at that premise, showing equality and diversity can grow together. Knock out the assumption and the objection falls with it.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Rebutting an objection by attacking the assumption beneath it.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The political scientist does not argue that accepting the critics' view would cause bad results.$batch06$), ($batch06$B$batch06$, $batch06$The objection is that equality forces a common mold. The assumption is that equality requires uniformity. That assumption is what gets attacked.$batch06$), ($batch06$C$batch06$, $batch06$The critics' motives are never mentioned.$batch06$), ($batch06$D$batch06$, $batch06$Nothing moves from a group to its members.$batch06$), ($batch06$E$batch06$, $batch06$No universal claim is defended against a counterexample.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT134-S1-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
